PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS departments(id TEXT PRIMARY KEY,name TEXT NOT NULL,code TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('student','faculty','admin')),title TEXT,department_id TEXT,avatar TEXT,office_location TEXT,bio TEXT,auto_approve INTEGER DEFAULT 0,created_at TEXT NOT NULL,FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE IF NOT EXISTS subjects(id TEXT PRIMARY KEY,name TEXT NOT NULL,code TEXT NOT NULL UNIQUE,department_id TEXT NOT NULL,FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE IF NOT EXISTS faculty_subjects(faculty_id TEXT NOT NULL,subject_id TEXT NOT NULL,PRIMARY KEY(faculty_id,subject_id),FOREIGN KEY(faculty_id) REFERENCES users(id),FOREIGN KEY(subject_id) REFERENCES subjects(id));
CREATE TABLE IF NOT EXISTS office_hours(id TEXT PRIMARY KEY,faculty_id TEXT NOT NULL,day_of_week INTEGER,start_time TEXT NOT NULL,end_time TEXT NOT NULL,location TEXT,status TEXT DEFAULT 'active',recurring INTEGER DEFAULT 1,specific_date TEXT,created_at TEXT NOT NULL,FOREIGN KEY(faculty_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS blocked_slots(id TEXT PRIMARY KEY,faculty_id TEXT NOT NULL,start_at TEXT NOT NULL,end_at TEXT NOT NULL,reason TEXT,FOREIGN KEY(faculty_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS appointments(id TEXT PRIMARY KEY,student_id TEXT NOT NULL,faculty_id TEXT NOT NULL,subject_id TEXT,start_at TEXT NOT NULL,end_at TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','confirmed','completed','cancelled','no_show','rejected')),reason TEXT,mode TEXT NOT NULL,location TEXT,cancelled_by TEXT,cancel_reason TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(student_id) REFERENCES users(id),FOREIGN KEY(faculty_id) REFERENCES users(id),FOREIGN KEY(subject_id) REFERENCES subjects(id));
CREATE INDEX IF NOT EXISTS idx_appointments_faculty_time ON appointments(faculty_id,start_at,end_at);
CREATE INDEX IF NOT EXISTS idx_appointments_student_time ON appointments(student_id,start_at);
CREATE TABLE IF NOT EXISTS waitlist(id TEXT PRIMARY KEY,student_id TEXT NOT NULL,faculty_id TEXT NOT NULL,subject_id TEXT,preferred_date TEXT,preferred_start TEXT,preferred_end TEXT,appointment_type TEXT DEFAULT 'in-person',status TEXT DEFAULT 'waiting',offered_appointment_id TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(student_id) REFERENCES users(id),FOREIGN KEY(faculty_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,type TEXT NOT NULL,title TEXT NOT NULL,message TEXT NOT NULL,read INTEGER DEFAULT 0,created_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS no_show_scores(id TEXT PRIMARY KEY,appointment_id TEXT UNIQUE NOT NULL,score INTEGER NOT NULL,risk_level TEXT NOT NULL,factors TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(appointment_id) REFERENCES appointments(id));
